// Parse input from backend orchestrate endpoint
const webhookRaw = $('Webhook').first().json;
const body = webhookRaw.body || webhookRaw;

const checkin_id = body.checkin_id || null;
const attempt_id = body.attempt_id || String($execution.id);
const tag = (body.tag || '').trim().toLowerCase();
const slug = body.slug || null;
const pnr = body.personnummer || null;
const name = body.name || null;

return [{
  json: {
    checkin_id,
    attempt_id,
    tag,
    slug,
    personnummer: pnr,
    name,
    _runEbas: !!pnr,
    _runStartgg: !!tag && !!slug,
  }
}];

// Successful negative verification is distinct from a failed or skipped check.
const ctx = $('Parse Input').first().json;
function readResult(nodeName, enabled, booleanField) {
  if (!enabled) return { ok: false, state: 'skipped', error: null };
  const unavailable = { ok: false, state: 'unavailable',
    error: { code: 'api_unavailable', message: nodeName + ' unavailable' } };
  try {
    const result = $(nodeName).first().json;
    if (result?.state === 'skipped' || result?.skipped === true) {
      return { ok: false, state: 'skipped', error: null };
    }
    if (!result || result.error || result.ok === false || result.state === 'unavailable' ||
        typeof result[booleanField] !== 'boolean') return unavailable;
    return { ok: true, state: result[booleanField] ? 'verified_true' : 'verified_false',
      value: result[booleanField], events: Array.isArray(result.events) ? result.events : [], error: null };
  } catch (error) {
    return unavailable;
  }
}
const ebas = readResult('eBas Check', ctx._runEbas, 'isMember');
const startgg = readResult('Start.gg Check', ctx._runStartgg, 'isRegistered');
return [{ json: {
  checkin_id: ctx.checkin_id, attempt_id: ctx.attempt_id,
  member: ebas.ok ? ebas.value : null,
  startgg: startgg.ok ? startgg.value : null,
  events: startgg.ok ? startgg.events : [],
  _ebasOk: ebas.ok, _startggOk: startgg.ok,
  _ebasState: ebas.state, _startggState: startgg.state,
  _ebasData: ebas.ok ? { member: ebas.value } : {},
  _startggData: startgg.ok ? { registered: startgg.value, events: startgg.events } : {},
  _ebasError: ebas.error, _startggError: startgg.error,
  fetched_at: new Date().toISOString(),
} }];

